import sys
import os

def main():
    if len(sys.argv) != 3:
        sys.exit(1)

    credentials_path = sys.argv[1]
    token = sys.argv[2]

    with open(credentials_path, 'r') as creds_file:
        lines = creds_file.readlines()

    for line in lines:
        parts = line.strip().split(':')
        if len(parts) != 2:
            continue
        current_token, directory = parts
        if current_token == token:
            requested_path = line.split(':', 1)[1].strip() + '/' + sys.stdin.readline().rstrip('\n')
            full_path = os.path.join(os.path.dirname(line.strip()), requested_path)
            try:
                with open(full_path, 'r') as file:
                    print(file.read())
                return
            except FileNotFoundError:
                pass

    print("Denied")

if __name__ == "__main__":
    main()

import sys
import os
import pathlib

def main():
    if len(sys.argv) != 3:
        print("Usage: python filegate.py <credentials_path> <token>", file=sys.stderr)
        sys.exit(0)

    credentials_path = sys.argv[1]
    token = sys.argv[2]

    try:
        with open(credentials_path, 'r') as creds_file:
            credentials = [line.strip().split(':') for line in creds_file if line.strip()]
    except IOError:
        print("Denied", file=sys.stderr)
        sys.exit(0)

    authorized_base = None
    for token_id, directory in credentials:
        if token_id == token:
            authorized_base = pathlib.Path(directory)
            break

    if authorized_base is None:
        print("Denied", file=sys.stderr)
        sys.exit(0)

    requested_path = sys.stdin.readline().rstrip('\n')
    if not requested_path:
        print("Denied", file=sys.stderr)
        sys.exit(0)

    requested_path = pathlib.Path(requested_path)
    if not requested_path.is_absolute():
        requested_path = authorized_base / requested_path

    try:
        if not requested_path.resolve().relative_to(authorized_base.resolve()).is_absolute():
            print("Denied", file=sys.stderr)
            sys.exit(0)
    except ValueError:
        print("Denied", file=sys.stderr)
        sys.exit(0)

    try:
        with open(requested_path, 'rb') as file:
            print(file.read(), end='')
    except IOError:
        print("Denied", file=sys.stderr)
        sys.exit(0)

if __name__ == "__main__":
    main()
